/**
 * The AV Engineering Standards & Design Manual (founder's directive of 11 Nov 2026, §08 Product C): its text.
 *
 * What this file is, and is not:
 *  - Every sentence here was written for this product, in its own words, from general engineering practice. Nothing is quoted or
 *    paraphrased from any organisation's documents, and no organisation, maker, product or person is named.
 *  - IT CARRIES NO PASS MARKS. A number in a standard needs a source: a standard the organisation licenses, a maker's specification,
 *    or a measured baseline of the organisation's own rooms. Where a rule needs a number, the rule names the VALUE to settle
 *    (`VALUES`) and the organisation records it, with its source, in its own edition (store.ts). No published standard is reproduced.
 *  - Where a rule is checked by a test the commissioning catalogue already holds, it names that test's id; the method, the verifier
 *    and the evidence the test accepts are the catalogue's (packages/commissioning-engine), not restated here.
 *  - It is a DRAFT written by the engineer and has not been reviewed by a practising professional. `CONTENT_STATUS` says so on every
 *    page and in every set of requirements generated from it.
 *  - It gives no fixing, rigging, mains or work-at-height instruction. Those are the qualified installer's, under the site's rules.
 */

export const CONTENT_STATUS = 'Draft. Written by Empathia’s engineer from general practice; not yet reviewed by a practising professional.';
export const NO_NUMBERS = 'This manual carries no pass marks. Where a rule needs a number, your organisation records the value and where it came from: a standard it licenses, the maker’s specification, or a measured baseline of its own rooms.';

/** When in a room's life a rule bites. A set of design requirements is made from the `design` rules; `commission` rules arrive through the catalogue's tests. */
export type Stage = 'govern' | 'design' | 'commission' | 'operate';
export interface Principle {
  id: string; stage: Stage; say: string; why: string;
  /** how a reviewer can tell it was done */
  check?: string;
  /** commissioning-catalogue test ids that check it */
  tests?: readonly string[];
  /** values the organisation must settle for this rule to be testable */
  values?: readonly string[];
  /** device families (the catalogue's) the rule concerns; absent = every room */
  families?: readonly string[];
  /** never waived: security, safety, a legal duty, or the integrity of evidence */
  noWaiver?: string;
}
export interface Chapter { id: string; title: string; aim: string; principles: readonly Principle[]; open: readonly string[]; see: ReadonlyArray<{ label: string; href: string }> }
export interface ValueDef { id: string; name: string; ask: string; from: string }

/** What an organisation settles for itself. The manual gives the question and where an answer may legitimately come from; never the answer. */
export const VALUES: readonly ValueDef[] = [
  { id: 'noise', name: 'Background noise limit', ask: 'The highest background noise acceptable at the seats with the system idle and the ventilation running, for each room type, and the measure it is stated in.', from: 'A building-acoustics standard your organisation licenses, or your acoustician’s criterion.' },
  { id: 'speech-level', name: 'Speech level at the seats', ask: 'The level of reproduced speech at a listener’s ear, and how much it may differ from seat to seat.', from: 'Your acoustician, or a measured baseline of rooms your users already rate well.' },
  { id: 'mic-level', name: 'Microphone level and headroom', ask: 'The nominal level of normal speech at the processor’s input and the headroom kept above loud speech.', from: 'The processor maker’s gain-structure guidance.' },
  { id: 'aec-reference', name: 'Echo-canceller reference level', ask: 'The nominal and peak level of the reference signal, and where in the chain it is taken.', from: 'The processor maker’s documentation for the canceller in use.' },
  { id: 'stability', name: 'Stability margin for reinforcement', ask: 'How far the operating level sits below the level at which the room becomes unstable, per room type.', from: 'Your acoustician; confirmed as achievable by measurement in a pilot room.' },
  { id: 'intelligibility', name: 'Speech intelligibility target', ask: 'The target, the method that measures it and the positions measured.', from: 'The intelligibility standard your organisation licenses; a single named method, not a choice of several.' },
  { id: 'reverberation', name: 'Reverberation time target', ask: 'The target for rooms used for speech, and the frequency range it is stated over.', from: 'A room-acoustics standard your organisation licenses, or your acoustician.' },
  { id: 'max-level', name: 'Maximum sound level', ask: 'The highest level any control, preset or fault may produce at a listener.', from: 'Your organisation’s occupational-health policy and the law where the building stands.' },
  { id: 'camera-height', name: 'Camera height', ask: 'The range of lens heights accepted for seated rooms and for presenter cameras, and from where height is measured.', from: 'A measured study of your own furniture and seated eye heights.' },
  { id: 'camera-fov', name: 'Camera field of view', ask: 'The widest view accepted before faces at the edge are too distorted or too small.', from: 'Derived per room from its geometry; the lens maker’s data.' },
  { id: 'face-size', name: 'Smallest face in frame', ask: 'How large the farthest participant must appear in the picture sent to the far end.', from: 'Your own viewing tests on the conferencing platforms you support.' },
  { id: 'display-size', name: 'Display sizing rule', ask: 'The rule that sizes an image from the farthest viewer and the smallest content that must be read.', from: 'The display-sizing standard your organisation licenses, cited by name.' },
  { id: 'switch-gap', name: 'Loss of picture on a source change', ask: 'The longest loss of picture accepted when the source changes.', from: 'The capability of the approved switching equipment, confirmed by test.' },
  { id: 'av-sync', name: 'Sound and picture alignment', ask: 'How far sound may lead or lag picture, and the instrument that measures it.', from: 'A broadcast or conferencing recommendation your organisation adopts by name.' },
  { id: 'qos', name: 'Quality-of-service markings', ask: 'The marking for each traffic class and where markings are trusted.', from: 'Your enterprise network policy and each transport’s own specification. Never invented in the AV standard.' },
  { id: 'storm-control', name: 'Storm-control thresholds', ask: 'The thresholds for each port profile, with the higher allowance media ports need.', from: 'Your network owner.' },
  { id: 'poe-reserve', name: 'Power-over-Ethernet reserve', ask: 'How much of a switch’s power budget is kept free.', from: 'Your network owner and the switch maker’s data.' },
  { id: 'firmware', name: 'Approved firmware', ask: 'The approved version for each device model, and the window in which it may be changed.', from: 'Your own testing in a pilot room, against each maker’s release notes.' },
  { id: 'cadence', name: 'Review rhythm', ask: 'How often the standard is reviewed, ports are sampled against their profiles and rooms are commissioned again.', from: 'Your governance board.' },
  { id: 'soak', name: 'Soak period', ask: 'How long a room runs, and through which checks, before it is called stable.', from: 'Your operations owner.' },
];
export const valueById = (id: string) => VALUES.find((v) => v.id === id);

