export const CHAPTERS: readonly Chapter[] = [
  {
    id: 'governance', title: 'Ownership and decisions', aim: 'Who holds the standard, who may change a room, and how a project is let through.',
    principles: [
      { id: 'G-01', stage: 'govern', say: 'One named person holds the standard. A different named person runs operations.', why: 'Someone measured on this week’s incidents will bend the standard to close them; someone who never answers an incident will write a standard nobody can run.', check: 'Both names stand at the front of the organisation’s edition.' },
      { id: 'G-02', stage: 'govern', say: 'The building, security and network owners each have a stated and limited say: the building owner on anything that touches power, furniture, ventilation or acoustics; the security owner on cameras, microphones, firmware, certificates and access; the network owner on routing, firewalls and access control, even where the AV team owns the AV standard.', why: 'A room is built on other people’s infrastructure. Rights that are written down are asked for; rights that are assumed are discovered late.' },
      { id: 'G-03', stage: 'govern', say: 'A supplier builds to the standard and is judged by commissioning evidence, never by a walk through the room.', why: 'A room that looks finished and a room that works are told apart only by tests.', check: 'Acceptance cites test records.', tests: ['independent_validation'] },
      { id: 'G-04', stage: 'govern', say: 'Every project passes three gates: a design review before anything is ordered, commissioning before anyone uses the room, and a review after people have used it.', why: 'Each gate catches what the one before it cannot see: a drawing cannot hear, and a commissioning visit cannot know how the room is used in its third month.' },
      { id: 'G-05', stage: 'design', say: 'Judge a design by its whole life: how it is run, maintained, upgraded and retired.', why: 'The first day is the cheapest day a room will ever have.', check: 'The design review records how each device is reached, updated and replaced.' },
      { id: 'G-06', stage: 'design', say: 'Prefer the estate’s consistency to one room’s optimum. A variation that helps one room and makes the estate harder to support needs a written exception.', why: 'Support staff carry the estate in their heads. Every one-off is a thing someone has to remember at the worst moment.', check: 'A variation from the room type’s package has an exception against it.' },
      { id: 'G-07', stage: 'design', say: 'Supportability is a design constraint. A design that needs a site visit, unwritten knowledge or the installer’s help for a routine fault is unfinished.', why: 'Most faults are routine, and most of the cost of a room is the years after handover.', check: 'Each device is reachable for remote diagnosis and its fault states are visible without entering the room.', tests: ['network_management_reach', 'integ_monitoring_enrol'] },
      { id: 'G-08', stage: 'govern', say: 'Documentation is part of the system. A record says why as well as what, and all of it lives in one place.', why: 'The person who needs the reason is rarely the person who made the decision.', tests: ['handover_runbook'] },
      { id: 'G-09', stage: 'design', say: 'Where two platforms could do the same job, or one maker’s processor is paired with another’s control system, write down once which does what, and repeat that split identically in every room.', why: 'Devices that each partly do the other’s job cannot be diagnosed: nobody can say which one is responsible for the fault.', check: 'The room type’s package states the split.', tests: ['interop_mixed_vendor'] },
      { id: 'G-10', stage: 'operate', say: 'Judge the standard by outcomes: incidents per room, time to restore, the share fixed without a visit, suppliers’ compliance, and what users say. Take a baseline before claiming an improvement.', why: 'A standard is a hypothesis about what makes rooms reliable. Without a baseline nothing has been tested.' },
    ],
    open: ['Who holds the standard, and who runs operations, in your organisation.', 'Whether the review after occupancy is done by the project or by operations.'],
    see: [PRO, EXC],
  },
  {
    id: 'rooms', title: 'Room types and design intent', aim: 'A small set of room types, each with a fixed package and a purpose commissioning can test.',
    principles: [
      { id: 'R-01', stage: 'govern', say: 'Keep a small number of room types. Each carries a fixed package: an equipment list, a network profile, a commissioning checklist, what is monitored, and who supports it.', why: 'A type is a promise that two rooms behave the same way, so that what is learned in one applies to the other.', check: 'The room’s record names its type; the catalogue lists what that type requires.' },
      { id: 'R-02', stage: 'design', say: 'Each room type has a written design intent, and the room is commissioned against that intent as well as against its tests.', why: 'A room can pass every measurement and still fail its purpose, for instance a training room in which questions from the back cannot be heard remotely.', check: 'The acceptance record states the intent and whether the room met it.', tests: ['user_function'] },
      { id: 'R-03', stage: 'design', say: 'Where the capacity ranges of two types meet, the record says which type the room is and why.', why: 'A room on a boundary gets the smaller type’s equipment and the larger type’s expectations unless someone decides.' },
      { id: 'R-04', stage: 'design', say: 'Size the image from the farthest viewer and the smallest content that has to be read, by a named sizing rule. Never from what fitted the wall last time.', why: 'An image too small for the back row is the commonest reason people stop using a room’s display.', check: 'The design states the farthest viewing distance, the content assumed and the rule applied.', values: ['display-size'], families: ['display'] },
      { id: 'R-05', stage: 'design', say: 'Record every dimension with how it was obtained: measured, taken from a drawing, or estimated. An estimated dimension cannot carry an acoustic or a coverage conclusion.', why: 'Coverage and reverberation are sensitive to the dimension most often guessed, the ceiling height.', check: 'The room’s geometry shows a source for each dimension.' },
      { id: 'R-06', stage: 'govern', say: 'A service tier, meaning how quickly a room is restored, is a different thing from its engineering type. Map one to the other explicitly.', why: 'Two identical rooms can deserve different response times; two different rooms can deserve the same.' },
      { id: 'R-07', stage: 'commission', say: 'Furniture and seating are part of the design. A room is tested with its furniture in place and its seats where people will sit.', why: 'Tables reflect, chairs absorb, and a camera framed on an empty room is framed on the wrong thing.', check: 'The test record states the furniture and seating present.', tests: ['design_conformance'] },
    ],
    open: ['Your capacity ranges, and the rule for rooms on a boundary.', 'The display-sizing standard your organisation adopts.'],
    see: [LITE, PRO, BUILD, SCOUT],
  },
  {
    id: 'display', title: 'Displays and the video signal', aim: 'A picture that arrives, stays, and can be read from every seat.',
    principles: [
      { id: 'D-01', stage: 'design', say: 'Fix the resolution and refresh rate for each room type, and keep them identical in identical rooms.', why: 'Most “no picture” faults are a negotiation between devices that ended somewhere unexpected. Fewer outcomes means fewer faults.', check: 'The room type’s package states them; the installed chain reports them.', tests: ['video_signal'], families: ['display'] },
      { id: 'D-02', stage: 'design', say: 'Decide where display-capability data is managed, fix it there, and do not pass it through from whichever display happens to be connected.', why: 'A capability profile that changes when a display is swapped changes what every source sends.', check: 'The same profile is read at every input of every room of the type.', tests: ['video_edid_handshake'], families: ['display'] },
      { id: 'D-03', stage: 'design', say: 'Name the sources that carry protected content, and confirm that every device between source and screen supports what they need. Content protection is never switched off as a fix.', why: 'Protected content that meets one unsupported device shows a black screen with no error, and switching protection off is a legal matter, not an engineering choice.', check: 'A protected source plays on every display it can be routed to.', tests: ['video_edid_handshake'], families: ['display'], noWaiver: 'Disabling content protection is a legal decision for the policy owner, not an engineering exception.' },
      { id: 'D-04', stage: 'design', say: 'Use certified cable within its rated length. Extenders come from the approved list only.', why: 'Marginal cabling fails intermittently, and intermittent faults cost the most to find.', check: 'Certification results are filed with the room.', tests: ['infra_cable_certification'] },
      { id: 'D-05', stage: 'commission', say: 'When the source changes, the picture comes back by itself, within the time your organisation accepts.', why: 'People judge a room in the seconds after they press a button.', check: 'Each source change is timed and nobody has to re-route by hand.', tests: ['video_switching', 'control_source_switching'], values: ['switch-gap'], families: ['display'] },
      { id: 'D-06', stage: 'commission', say: 'Check that content can be read from the farthest seat and from the most oblique seat, under the room’s real lighting.', why: 'A display that is the right size can still be unreadable through glare or off its axis.', check: 'The record names the seats checked and the lighting scene.', tests: ['video_display_calibration', 'env_lighting_levels'], families: ['display'] },
      { id: 'D-07', stage: 'commission', say: 'Sound and picture arrive together. Measure the alignment with an instrument where one is available; otherwise record what was seen and label it as an observation.', why: 'Calling an observation a measurement is how a report loses its standing when it is challenged.', check: 'The record states the method used.', tests: ['video_av_sync'], values: ['av-sync'] },
    ],
    open: ['Where capability data is managed in each room type.', 'Which sources carry protected content.'],
    see: [CX, DRAW],
  },
  {
    id: 'camera', title: 'Camera placement and coverage', aim: 'Every person in the room seen as well as every other, on every platform, for a reason that is written down.',
    principles: [
      { id: 'C-01', stage: 'design', say: 'Camera placement is an engineering decision, justified in writing for each room: where each camera is, its height and angle, what it is meant to cover and why.', why: 'A placement nobody can explain cannot be repeated in the next room or defended when someone asks for it to be moved.', check: 'The design carries a justification for each camera.', families: ['camera'] },
      { id: 'C-02', stage: 'design', say: 'Place the main camera near the eye line of a seated conversation. Avoid a steep view from above or below.', why: 'A view from the ceiling makes a meeting look like surveillance, and people behave accordingly.', check: 'Lens height is within your organisation’s range, or the reason it is not is recorded.', values: ['camera-height'], families: ['camera'] },
      { id: 'C-03', stage: 'design', say: 'Seats at the edges and corners are framed as well as seats in the centre.', why: 'The people at the edge of a picture are the ones remote colleagues stop addressing.', check: 'The coverage table has a row for every seat.', tests: ['camera_fov'], families: ['camera'] },
      { id: 'C-04', stage: 'design', say: 'Cover named zones on purpose: the seated participants, the place a presenter stands, the surface people write on. Leave empty floor and ceiling out on purpose too.', why: 'A camera that shows everything shows each person small.', families: ['camera'] },
      { id: 'C-05', stage: 'design', say: 'The placement works on every conferencing platform your organisation supports, without a correction for each. Automatic framing and tracking are aids, never something the design relies on.', why: 'Automatic features change with every software release; the wall the camera is fixed to does not.', check: 'The room is tested with automatic framing off.', tests: ['video_camera_tracking', 'uc_media'], families: ['camera'] },
      { id: 'C-06', stage: 'design', say: 'Give every camera a role: the main view of seated participants, a second view of the presenter, or an additional view where one camera cannot treat every seat fairly. Keep cameras few and their arrangement symmetrical.', why: 'Each extra camera is another view to switch to, and switching is where rooms confuse people.', families: ['camera'] },
      { id: 'C-07', stage: 'commission', say: 'Check the field of view against the seats as they really are: every seat fully in frame, no head or shoulder cut at the edge, no wide band of ceiling or floor. Digital zoom does not correct a camera in the wrong place.', why: 'The drawing shows where the table was meant to go.', check: 'A still from each camera is filed with the seats occupied or marked.', tests: ['camera_fov'], values: ['camera-fov', 'face-size'], families: ['camera'] },
      { id: 'C-08', stage: 'design', say: 'Justify coverage with a model before installation and a test after it. State the result seat by seat (seat, camera, seen or not, size in frame), never as a single percentage.', why: 'A percentage hides which seat is the one that cannot be seen.', check: 'The design holds the modelled table; the commissioning record holds the tested one, and says which is which.', tests: ['camera_fov'], families: ['camera'] },
      { id: 'C-09', stage: 'design', say: 'Place the camera with the display and the light in mind: close to the display so that looking at content and looking at people are nearly the same gaze; no window behind the participants; a position where exposure holds across the room’s lighting scenes.', why: 'A camera’s automatic correction should be trimming a good picture, not rescuing a bad one.', tests: ['video_camera_exposure', 'env_lighting_levels'], families: ['camera'] },
      { id: 'C-10', stage: 'operate', say: 'Lighting scenes and camera settings are changed together. A change to a lighting scene brings a re-check of exposure and colour.', why: 'The two are tuned against each other, and usually by different people.', tests: ['lighting_scenes', 'video_camera_exposure'], families: ['camera', 'lighting'] },
      { id: 'C-11', stage: 'design', say: 'Camera switching can be explained to the person in the room: by hand, by a named preset, or assisted. No switching logic that nobody can describe, and no change of picture in an important meeting that the people in it cannot see happening. Presets are governed like any other configuration.', why: 'People trust a room they can predict.', check: 'Each preset recalls the same view every time.', tests: ['camera_preset', 'control_camera'], families: ['camera'] },
      { id: 'C-12', stage: 'commission', say: 'A camera’s mounting is secure, free of vibration and drift, at the height and angle shown on a scaled drawing. Fixing it is the qualified installer’s work under the site’s rules.', why: 'A camera that sags a little each month fails slowly enough that nobody reports it.', check: 'The installation safety check is recorded by the person qualified to make it.', tests: ['safety_install'], families: ['camera'], noWaiver: 'Installation safety is confirmed by a qualified person and is not open to exception.' },
    ],
    open: ['Your accepted camera heights, measured against your own furniture.', 'How large the farthest face must be, on the platforms you support.'],
    see: [LITE, DRAW, BUILD, CX],
  },
  {
    id: 'audio', title: 'Audio: levels, echo and measurement', aim: 'Speech that is clear at both ends, and measurements another engineer could repeat.',
    principles: [
      { id: 'A-01', stage: 'commission', say: 'Record the conditions before any number: the room and its type, who measured, when, who was in the room, whether the ventilation was running, each instrument with its calibration status, and the test signal.', why: 'Two readings taken under different conditions cannot be compared, and nobody remembers the conditions afterwards.', check: 'Every measurement in the record has its conditions.', families: ['dsp'] },
      { id: 'A-02', stage: 'commission', say: 'Measure; do not estimate. Where something was judged by ear or eye, the record says so. The engineer signs to which is which.', why: 'A record is only as strong as its weakest unlabelled entry.', check: 'Each entry states how it is known.', families: ['dsp'] },
      { id: 'A-03', stage: 'design', say: 'Set the gain structure first: input levels, then headroom kept through every stage. A limiter that acts on ordinary speech, or a need for heavy compression or deep corrective equalisation, means something upstream is wrong.', why: 'Problems fixed with more gain or more processing come back as noise, distortion or instability.', check: 'Levels are read at each stage with normal and with loud speech.', tests: ['audio_gain'], values: ['mic-level'], families: ['dsp'] },
      { id: 'A-04', stage: 'design', say: 'Exactly one echo canceller owns each audio path: the room’s processor or the conferencing device, never both. Where the room’s processor does the work, the conferencing application’s own echo cancellation, automatic gain and noise suppression are off.', why: 'Two cancellers in series each treat the other’s output as the room and fight.', check: 'A two-way conversation with both ends speaking at once is clean at the far end.', tests: ['audio_aec'], families: ['dsp'] },
      { id: 'A-05', stage: 'design', say: 'The echo canceller’s reference is the far-end signal as it is sent to the loudspeakers, and nothing else. The room’s own microphones never appear in it. The design states exactly where in the chain the reference is taken.', why: 'A canceller removes whatever its reference contains. Give it the local talker and it removes the local talker.', check: 'The reference meter is still while only people in the room speak.', tests: ['audio_aec'], values: ['aec-reference'], families: ['dsp'] },
      { id: 'A-06', stage: 'design', say: 'Where an automatic mixer and an echo canceller meet, the design states the rule it follows, cancelling each microphone channel before mixing or using an array’s own processed output, and why that rule suits the microphones in the room.', why: 'A mixer ahead of a single canceller changes the echo path every time a different microphone opens, and the canceller has to learn the room again.', check: 'The design file matches the stated rule.', families: ['dsp'] },
      { id: 'A-07', stage: 'commission', say: 'Measure background noise at the seats with the system idle and the ventilation running. The limit is your organisation’s, by room type. A larger room, where talkers sit farther from the microphones, needs a background at least as quiet as a small one.', why: 'Noise is the floor every other audio decision stands on.', check: 'The reading, its positions and its conditions are in the record.', tests: ['audio_noise_floor'], values: ['noise'], families: ['dsp'] },
      { id: 'A-08', stage: 'commission', say: 'Measure reproduced speech at the listeners’ ears, at the front, the middle and the back, and compare seat with seat.', why: 'A room that is right on average can be too loud at the front and too quiet at the back.', check: 'The record gives each position.', tests: ['acoustic_coverage'], values: ['speech-level'], families: ['dsp'] },
      { id: 'A-09', stage: 'commission', say: 'Where intelligibility is part of acceptance, it is measured, by one named method, at stated positions. A listening panel is a useful observation and is recorded as one.', why: 'Different methods do not give equivalent results, and an acceptance rule cannot rest on a test marked optional.', check: 'The record names the method and the positions.', tests: ['audio_intelligibility'], values: ['intelligibility'], families: ['dsp'] },
      { id: 'A-10', stage: 'commission', say: 'Every seat is picked up. Coverage zones are mapped to seats, and pickup areas that cover no seat are closed.', why: 'An open zone over an empty corner contributes only noise and reverberation.', check: 'Each seat is spoken from and seen on a meter.', tests: ['audio_mic_pickup'], families: ['dsp'] },
      { id: 'A-11', stage: 'commission', say: 'Test with people in the room. Occupancy is a recorded condition, and larger rooms are tested with several people speaking in turn and together.', why: 'Processing that behaves in an empty room can misbehave in a full one.', families: ['dsp'] },
      { id: 'A-12', stage: 'design', say: 'A limiter sets a ceiling on the level the room can produce. It acts on a fault or on misuse, never on ordinary speech.', why: 'Hearing is not recoverable.', check: 'The ceiling is demonstrated and recorded.', tests: ['audio_limiter_levels'], values: ['max-level'], families: ['dsp'], noWaiver: 'A limit on sound level protects hearing and is not open to exception.' },
      { id: 'A-13', stage: 'design', say: 'The processor’s design file can be read by someone who did not write it: meaningful names, labelled blocks, notes inside the file, no unused blocks left in a signal path. It is archived with the room.', why: 'The file is the only complete description of how the room’s audio works.', check: 'The archived file is the one running, and the approved firmware is installed.', tests: ['dsp_config_backup', 'audio_dsp_firmware'], values: ['firmware'], families: ['dsp'] },
    ],
    open: ['Every value this chapter names. None is set by this manual.', 'The single intelligibility method your organisation accepts.'],
    see: [CX, BUILD, KNOW],
  },
  {
    id: 'reinforcement', title: 'Voice reinforcement in hybrid rooms', aim: 'People at the back hear the people at the front, and the far end hears everyone, without one spoiling the other.',
    principles: [
      { id: 'V-01', stage: 'design', say: 'Choose the audio arrangement on purpose and name it in the design: conferencing only; conferencing with voice reinforcement in the room; or the same with ceiling and presenter microphones together.', why: 'Reinforcement added to a conferencing design afterwards is where unstable rooms come from.', families: ['dsp'] },
      { id: 'V-02', stage: 'design', say: 'Keep the conferencing path and the reinforcement path apart by design. Condition the microphone signal once, then split it. The conferencing branch is tuned for the listener at the far end and holds the echo canceller. The reinforcement branch is tuned for stability in the room and holds none.', why: 'The two branches serve different listeners with different needs. One chain cannot be right for both.', check: 'The design file shows the split ahead of the canceller.', families: ['dsp'] },
      { id: 'V-03', stage: 'design', say: 'A change of level in the room does not change what the far end hears, and reinforcement does not change what the echo canceller is given as its reference.', why: 'Otherwise the person adjusting the room’s volume is unknowingly adjusting the call.', check: 'The far-end level is read while the room’s level is moved through its range.', tests: ['audio_zone_routing', 'control_audio'], families: ['dsp'] },
      { id: 'V-04', stage: 'design', say: 'A talker’s microphone is not sent to the loudspeakers nearest that talker.', why: 'The shortest path from loudspeaker to microphone is the one that rings first.', check: 'The routing matrix shows each zone without its own microphones.', tests: ['audio_zone_routing'], families: ['dsp'] },
      { id: 'V-05', stage: 'design', say: 'Use several loudspeaker zones, each quiet and close to its listeners, in place of one loud zone. Keep loudspeakers away from, and aimed away from, the areas microphones pick up. Align the zones in time so speech stays coherent.', why: 'Every listener gets enough level from a nearby source, and the microphones get as little of it as possible.', tests: ['acoustic_coverage', 'audio_zone_routing'], families: ['dsp'] },
      { id: 'V-06', stage: 'design', say: 'Order the reinforcement branch so that each stage has less to do: broad tonal shaping; automatic mixing, so fewer microphones are open; a few narrow filters only where the room needs them; a limiter as the ceiling; then the routing to zones, with each zone’s delay and loudspeaker correction.', why: 'Narrow filters and limiters are safety nets. A design that leans on them has no margin left.', families: ['dsp'] },
      { id: 'V-07', stage: 'design', say: 'The user’s controls are bounded: a limited range for each zone and named presets. No control without limits is exposed. Prove it by driving every control to its extreme and showing that the room stays stable.', why: 'Rooms drift to wherever their controls allow.', check: 'The test at the limits of the controls is in the record.', tests: ['control_audio', 'audio_limiter_levels'], families: ['dsp'] },
      { id: 'V-08', stage: 'commission', say: 'The stability margin is found by a controlled procedure: limiter engaged, level capped, the people present warned, carried out by someone trained to do it. It is never found by raising the gain of a live microphone until the room rings.', why: 'Uncontrolled feedback can damage hearing and loudspeakers in less time than it takes to reach the fader.', check: 'The record names the procedure followed and who carried it out.', values: ['stability'], families: ['dsp'], noWaiver: 'A safe procedure for finding instability protects hearing and is not open to exception.' },
      { id: 'V-09', stage: 'design', say: 'State in the design how much reinforcement the chosen microphones can realistically give, and compare it with what is measured. If the margin cannot be met, change the microphone approach; do not lower the margin.', why: 'A microphone far from the talker has little gain to give before the room becomes unstable, whatever the processing.', families: ['dsp'] },
      { id: 'V-10', stage: 'design', say: 'Measure the room’s noise and reverberation before promising reinforcement in it.', why: 'In a noisy or reverberant room the honest answer may be acoustic treatment or microphones nearer the talkers.', tests: ['reverberation_rt60', 'audio_noise_floor'], values: ['reverberation', 'noise'], families: ['dsp'] },
    ],
    open: ['The procedure your organisation uses to find the stability margin, and who is trained to run it.', 'The margin itself, confirmed as achievable in a pilot room.'],
    see: [CX, BUILD, SIGNAL],
  },
  {
    id: 'control', title: 'Control, room states and recovery', aim: 'A room that says what state it is in and finds its own way back to a good one.',
    principles: [
      { id: 'K-01', stage: 'design', say: 'The room’s states are defined (idle, in use, in a call, at fault) and the panel shows which one the room is in.', why: 'A person facing a panel needs to know first whether the room is working.', check: 'Each state is reached and seen on the panel.', tests: ['control_ui', 'control_error_states'], families: ['touch_panel'] },
      { id: 'K-02', stage: 'design', say: 'What the room does when it starts is chosen and safe. Whether microphones are live after a restart is a privacy decision, made by the security owner.', why: 'A default nobody chose is still a decision; it was just made by accident.', check: 'The start-up state is recorded and approved.', families: ['touch_panel'] },
      { id: 'K-03', stage: 'commission', say: 'Recovery is tested, using only what a user or a support engineer can safely reach: restart the processor, unplug and reconnect the network, unplug and reconnect a microphone, switch a display or an amplifier off and on, restart the control system. Each time the room returns to a known good state without anyone reconfiguring it.', why: 'Every one of these will happen in the room’s first year.', check: 'Each action and the state the room returned to are in the record.', tests: ['control_error_states', 'control_macros'], families: ['touch_panel'] },
      { id: 'K-04', stage: 'design', say: 'There is a defined way to hold a meeting when the control system is offline.', why: 'The control system is one more thing that can fail, and it should not take the meeting with it.', check: 'A call is made with the control system disconnected.', tests: ['control_error_states'], families: ['touch_panel'] },
      { id: 'K-05', stage: 'commission', say: 'Mute is checked against the signal, on a meter, not against the colour of a button.', why: 'A mute indicator and the audio it claims to describe are separate things that are usually, not always, in step.', check: 'The meter falls silent when the room shows muted.', tests: ['control_audio'], families: ['touch_panel', 'dsp'] },
      { id: 'K-06', stage: 'commission', say: 'The control program and the interface build running in the room are recorded and archived.', why: 'Nobody should have to guess which version is in the room.', check: 'The archived build matches the running one.', tests: ['control_program_version'], families: ['touch_panel'], noWaiver: 'A record of what is running is evidence, and evidence is not open to exception.' },
      { id: 'K-07', stage: 'design', say: 'Whether a panel talks directly to the calendar service or runs inside the conferencing platform is a decision about dependence. Record, per room: which mode, what it depends on, and who owns its failures.', why: 'A panel inside the platform shares the platform’s sign-in and its outages; a panel outside it is one more thing to manage. Both are defensible. Neither should be an accident.', tests: ['uc_calendar'], families: ['touch_panel'] },
      { id: 'K-08', stage: 'commission', say: 'The room’s clock is right, and it takes its time from the source the enterprise names.', why: 'Calendars, certificates and logs all fail in confusing ways when it is not.', tests: ['control_time_sync'], families: ['touch_panel'] },
    ],
    open: ['The state of microphones after a restart, decided by your security owner.', 'The panel mode for each room type.'],
    see: [CX, ASSURE],
  },
  {
    id: 'network', title: 'Network: segments, ports and media', aim: 'AV on the network as one managed thing, with nothing left to chance and nothing invented by the AV team.',
    principles: [
      { id: 'N-01', stage: 'design', say: 'Separate traffic by kind: real-time audio, real-time video, control, management, and access to enterprise and cloud services. Each segment has one stated purpose. AV devices do not sit on users’ segments.', why: 'A segment with one purpose can have one policy, and a fault in it has one kind of cause.', check: 'Each device is on the segment its class belongs to.', tests: ['network_vlan'] },
      { id: 'N-02', stage: 'design', say: 'Keep the edge simple. An endpoint connects to a port that carries one segment; only uplinks carry several. Routing, policy and address assignment live where the enterprise network already runs them.', why: 'An AV switch that routes or hands out addresses becomes a second, undocumented network.', tests: ['network_port_profile'], families: ['network_switch'] },
      { id: 'N-03', stage: 'design', say: 'Present AV to the enterprise network as one managed area behind a defined boundary, and write down exactly what crosses it: control, monitoring, and the cloud services conferencing needs. Do not claim that media never leaves if a conferencing device has to reach the cloud.', why: 'The network owner can approve a boundary that is described accurately, and will rightly distrust one that is not.', check: 'The list of what crosses the boundary matches what the firewall allows.', tests: ['network_reachability'] },
      { id: 'N-04', stage: 'design', say: 'Choose on purpose between ending AV segments at a routed boundary and carrying them on an uplink to the core, and record why.', why: 'The first gives smaller fault domains and needs more coordination; the second is simpler at the edge, and one mistake on an uplink affects many rooms.' },
      { id: 'N-05', stage: 'design', say: 'An uplink lists the segments it carries; never “all”. Its untagged default is an unused segment or none. It is labelled at both ends. Whether it has a second path is a stated decision: either a single uplink is accepted in writing as a single point of failure, or a second path is designed with loop protection.', why: 'An uplink is where one error reaches the most rooms.', check: 'Both ends of each uplink show the same list.', tests: ['network_port_profile', 'infra_labeling'], families: ['network_switch'] },
      { id: 'N-06', stage: 'design', say: 'One class of device, one port profile, kept as a named template. No port is configured by hand as a one-off.', why: 'A profile can be audited. A hand-built port can only be rediscovered.', check: 'Each port matches its device’s profile.', tests: ['network_port_profile'], values: ['storm-control'], families: ['network_switch'] },
      { id: 'N-07', stage: 'design', say: 'Multicast is designed. Group-membership snooping is on; where the querier sits is chosen for each site; streams cross between segments only where they must, and then explicitly. Check that media does not flood ports that never asked for it.', why: 'Multicast left to defaults works in the pilot room and floods the building in the tenth.', check: 'A non-media port is watched while streams run.', tests: ['network_multicast'] },
      { id: 'N-08', stage: 'design', say: 'Quality of service follows the enterprise marking scheme. The table of markings and the point where they are trusted are written down. The AV standard does not invent markings.', why: 'A marking the rest of the network does not honour does nothing, and one it honours by accident can starve voice.', check: 'Markings are read at the far side of the boundary.', tests: ['network_qos'], values: ['qos'] },
      { id: 'N-09', stage: 'design', say: 'Power over Ethernet is budgeted in design, against the sum of what each port’s device may draw, and verified at commissioning.', why: 'A switch that runs out of power drops the last device connected, which is rarely the one anyone suspects.', check: 'The budget and the measured draw are both in the record.', tests: ['poe_budget', 'power_budget'], values: ['poe-reserve'], families: ['network_switch'] },
      { id: 'N-10', stage: 'design', say: 'The timing leader for networked audio is chosen, recorded and kept inside the media segment.', why: 'Whichever device wins by default will change when a device is replaced.', check: 'The device acting as leader is the one the design names.', tests: ['network_media_clock'], families: ['dsp'] },
      { id: 'N-11', stage: 'design', say: 'Document every segment and port: its purpose, the kinds of device on it, what may talk to what, the diagrams, the port map and the addressing. An organisation’s own numbering stays in its own edition and is never published.', why: 'Undocumented use of a segment is how a clean design decays.', tests: ['network_addressing', 'infra_labeling'] },
      { id: 'N-12', stage: 'design', say: 'Where policy requires ports to authenticate devices, the fallback for an AV device that cannot is agreed with the network owner and written down.', why: 'The alternative is an exception made at two in the morning by whoever is on call.' },
      { id: 'N-13', stage: 'operate', say: 'Prevent drift. Profiles are kept as templates, a deviation is approved and recorded, and ports are sampled against their templates on a schedule.', why: 'Configuration drifts one reasonable change at a time.', check: 'The last sample and what it found are on record.', tests: ['network_config_backup', 'network_firmware_baseline'], values: ['cadence'], families: ['network_switch'] },
    ],
    open: ['Routed or trunked, per site.', 'Storm-control thresholds, quality-of-service markings and the authentication fallback: all the network owner’s to give.', 'Whether a single uplink is accepted.'],
    see: [FI, CX, PRO],
  },
  {
    id: 'security', title: 'Security and device hygiene', aim: 'AV devices held to the same standard as any other computer on the network.',
    principles: [
      { id: 'S-01', stage: 'commission', say: 'No device keeps a default credential.', why: 'Default credentials are published.', check: 'Every device is tried with its maker’s default and refuses.', tests: ['cyber_default_credentials'], noWaiver: 'A critical security requirement; not open to exception.' },
      { id: 'S-02', stage: 'design', say: 'Management interfaces are reachable only from the management segment.', why: 'An interface that can configure a device should not be reachable from a meeting-room wall port.', check: 'A management page is tried from a user segment and does not answer.', tests: ['cyber_management_isolation'], noWaiver: 'A critical security requirement; not open to exception.' },
      { id: 'S-03', stage: 'operate', say: 'Administration follows least privilege and the enterprise’s own identity system. No shared administrator accounts. Service accounts are reviewed.', why: 'An action nobody can be named for is an action nobody can be asked about.', check: 'Each account has an owner and a reason.', tests: ['cyber_accounts'], noWaiver: 'A critical security requirement; not open to exception.' },
      { id: 'S-04', stage: 'operate', say: 'Firmware is governed: an approved version for each model, obtained from the maker’s signed channel, changed in a maintenance window, with a tested way back.', why: 'Firmware is both the commonest fix and the commonest cause.', check: 'Installed versions match the approved list, and a rollback has been rehearsed.', tests: ['cyber_firmware_signed', 'interop_firmware_matrix', 'rollback_drill'], values: ['firmware'] },
      { id: 'S-05', stage: 'operate', say: 'Every device is in the inventory and can be found on the network. No unmanaged switches. No services nobody listed.', why: 'What is not in the inventory is not patched, not monitored and not noticed when it goes missing.', check: 'What is found on the network is compared with the register.', tests: ['identity_asset', 'integ_monitoring_enrol'], noWaiver: 'Asset identity is the basis of every other record; not open to exception.' },
      { id: 'S-06', stage: 'design', say: 'Management traffic is encrypted and devices carry certificates wherever they support them.', why: 'Credentials sent in clear are credentials shared with the network.', tests: ['cyber_tls'] },
      { id: 'S-07', stage: 'operate', say: 'Devices send their logs to the monitoring host.', why: 'The log on a device that has just failed is the one you cannot read.', tests: ['cyber_logging'] },
      { id: 'S-08', stage: 'govern', say: 'A control that operators routinely work around has failed. Repair the control; do not blame the operators.', why: 'People under time pressure take the path that works. The standard’s job is to make the safe path the one that works.' },
      { id: 'S-09', stage: 'design', say: 'Cameras and microphones are a privacy matter. Recording, what is live by default and how people in the room can tell are approved by the security owner.', why: 'People are entitled to know when a room can see or hear them.', check: 'An indicator shows when the room is capturing, and the approval is on record.', tests: ['recording_streaming'], families: ['camera', 'dsp'], noWaiver: 'Privacy approvals belong to the security owner and are not open to an engineering exception.' },
    ],
    open: ['The approved firmware for each model.', 'Who reviews service accounts, and how often.'],
    see: [FI, ASSURE, KNOW],
  },
  {
    id: 'accessibility', title: 'Accessibility', aim: 'A room every colleague can use, with the legal duty as the floor and not the ceiling.',
    principles: [
      { id: 'X-01', stage: 'design', say: 'What the law requires where the building stands is the minimum. The design names each requirement that applies and who confirmed that it does.', why: 'Accessibility duties differ by place and by kind of room, and an engineer’s recollection is not a legal reading.', check: 'The record names the requirement and the person who confirmed it.', noWaiver: 'A legal duty is not open to an engineering exception.' },
      { id: 'X-02', stage: 'design', say: 'Rooms of the types that call for it provide assistance for people who are hard of hearing, and the path that feeds it is tested like any other output.', why: 'An assistive system nobody tested is the one found not to work on the day it is needed.', check: 'The assistive output is listened to on a receiver.', tests: ['access_hearing', 'audio_assisted_listening'], families: ['dsp'] },
      { id: 'X-03', stage: 'commission', say: 'Live captions can be turned on in the conferencing platform from the room.', why: 'Captions serve people who are deaf or hard of hearing, people in a second language, and anyone when the sound is poor.', tests: ['access_captions'], families: ['uc'] },
      { id: 'X-04', stage: 'design', say: 'Controls can be reached and operated by someone seated and by someone with limited reach or grip.', why: 'A panel mounted for a standing installer excludes people.', check: 'Height, clearance and the force needed are checked against the requirement named under X-01.', tests: ['access_reach'], families: ['touch_panel'], noWaiver: 'An accessibility requirement the catalogue marks as never waived.' },
      { id: 'X-05', stage: 'design', say: 'The interface has enough contrast and large enough text to be read from where a person stands or sits to use it.', why: 'Panels are read at arm’s length, in rooms dimmed for a presentation.', tests: ['access_contrast'], families: ['touch_panel'] },
      { id: 'X-06', stage: 'design', say: 'Seat-by-seat coverage, for cameras and for microphones, includes the places a wheelchair user will sit and the place a person who remains standing will stand.', why: 'Coverage drawn only for the chairs on the plan leaves out the people who do not use them.', tests: ['camera_fov', 'audio_mic_pickup'], families: ['camera', 'dsp'] },
      { id: 'X-07', stage: 'design', say: 'Anything the room says with a sound it also shows, and anything it shows with colour alone it also says in words.', why: 'Mute, call state and faults matter to people who cannot hear a tone or tell red from green.', tests: ['control_ui'], families: ['touch_panel'] },
    ],
    open: ['The accessibility requirements that apply to each of your sites, confirmed by someone qualified to say.'],
    see: [CX, BUILD],
  },
  {
    id: 'commissioning', title: 'Commissioning and acceptance', aim: 'A record that contains what was observed, by whom and how, and nothing else.',
    principles: [
      { id: 'M-01', stage: 'commission', say: 'Every record opens with what it is a record of: the site, the room and its type, the engineer, the date, the software versions, each processor’s model and firmware, the control platform and the network segments.', why: 'A result that cannot be tied to a version of the room describes a room that may no longer exist.', tests: ['identity_asset', 'control_program_version'] },
      { id: 'M-02', stage: 'commission', say: 'Follow each signal from its source to its destination and confirm it at every stage: nothing bypassed, nothing left in the path that is not used.', why: 'A room that works end to end with one stage bypassed will stop working when someone restores the stage.', tests: ['user_function', 'uc_media'] },
      { id: 'M-03', stage: 'commission', say: 'A record holds only what was observed. No form arrives with boxes already ticked or conclusions already printed, and an empty list of issues is not evidence that there were none.', why: 'A signed form that was favourable before anyone entered the room is worth nothing in a dispute, and everyone who reads it knows.', check: 'Every pass in the record has evidence behind it.', noWaiver: 'The integrity of evidence is not open to exception.' },
      { id: 'M-04', stage: 'commission', say: 'Each piece of evidence says how it is known: measured with an instrument, observed by a person, reported by the device, or declared by someone.', why: 'These are different strengths of evidence and a reader is entitled to tell them apart.', check: 'The catalogue lists, for each test, the kinds of evidence it accepts.' },
      { id: 'M-05', stage: 'commission', say: 'An estimate from a design tool and a reading from the running system are kept visibly apart.', why: 'A calculated figure presented as a measurement is the commonest way an honest report misleads.' },
      { id: 'M-06', stage: 'commission', say: 'Commissioning includes a real call with someone at the far end, and an issue log in which every issue has an owner and a date.', why: 'Half of a meeting room’s performance can only be judged from somewhere else.', tests: ['uc_media', 'user_function'] },
      { id: 'M-07', stage: 'commission', say: 'There are three outcomes: accepted; accepted with documented exceptions; not accepted. Acceptance comes from someone other than the person who did the work.', why: 'Nobody is a fair judge of their own installation.', tests: ['independent_validation'], noWaiver: 'Independent acceptance is a separation of duties and is not open to exception.' },
      { id: 'M-08', stage: 'operate', say: 'A room is commissioned more than once: at handover; after any change of hardware, firmware or configuration; on a schedule; and after repeated complaints or a platform update.', why: 'A room is accepted in the state it was in that day.', check: 'A change to the room reopens the tests that depend on what changed.', tests: ['post_repair_function', 'dependency_check'], values: ['cadence'] },
      { id: 'M-09', stage: 'commission', say: 'What is installed is checked against the drawing, and each device’s identity is confirmed on site.', why: 'A test result attaches to a device. If the device is not the one in the record, the result attaches to nothing.', tests: ['design_conformance', 'identity_asset'], noWaiver: 'Asset identity and conformance are the basis of every other record; not open to exception.' },
      { id: 'M-10', stage: 'commission', say: 'The safety of the installation is confirmed by a person qualified to confirm it, under the site’s rules.', why: 'This manual is about whether a room works. Whether it is safe is a matter for people with the training and the authority to say so.', tests: ['safety_install', 'safety_review', 'occupancy_safety'], noWaiver: 'A mandatory safety requirement; not open to exception.' },
      { id: 'M-11', stage: 'commission', say: 'A room is called stable only after it has run for the period, and through the checks, your organisation sets.', why: 'Some faults need a weekend, a restart or a full calendar to appear.', values: ['soak'] },
    ],
    open: ['Who accepts a room, by room type.', 'The soak period and the schedule for commissioning again.'],
    see: [CX, ASSURE, KNOW, BUILD],
  },
  {
    id: 'suppliers', title: 'Suppliers and handover', aim: 'A supplier who knows the standard before starting and shows the work at the end.',
    principles: [
      { id: 'U-01', stage: 'govern', say: 'Before work starts, the supplier acknowledges the standard. At handover the supplier attests that the room complies, that the documentation is delivered, that no temporary credentials remain and that the room is ready to be operated.', why: 'A standard first shown to a supplier at handover is a list of complaints.', tests: ['cyber_default_credentials', 'handover_support_path'] },
      { id: 'U-02', stage: 'govern', say: 'One compliance checklist follows the project: it sets expectations before installation, it is the basis of the design review, and it is enforced at handover. Each line is met, met with a documented exception, or not met.', why: 'The same list at each gate means nobody is surprised at the last one.' },
      { id: 'U-03', stage: 'commission', say: 'The supplier delivers the drawings as built, exports of every configuration, the firmware versions, the network port map, the commissioning results and the sign-offs.', why: 'These are what the next engineer needs, and they are cheapest to produce on the day the work is finished.', tests: ['infra_rack_match', 'dsp_config_backup', 'network_config_backup', 'handover_warranty'] },
      { id: 'U-04', stage: 'commission', say: 'The supplier shows the work: the values measured, the design file, each limiter’s threshold and the reason for it, the echo-canceller reference as verified, and a dated log of what passed and failed.', why: 'If these cannot be produced, nobody knows the state of the room, including the supplier.' },
      { id: 'U-05', stage: 'govern', say: 'Sign-off does not move responsibility for a fault that was already there. Who pays to put it right is for the contract and the people who draft it; this manual does not say.', why: 'An engineering standard should not be read as contract terms.' },
      { id: 'U-06', stage: 'commission', say: 'The people who will use and support the room are trained, the path for support is confirmed with names, and the agreed spares are on the shelf.', why: 'A room nobody was shown how to use is reported as broken.', tests: ['handover_training', 'handover_support_path', 'handover_spares', 'handover_runbook'], noWaiver: 'The catalogue marks a confirmed support path as never waived.' },
      { id: 'U-07', stage: 'govern', say: 'A new product is assessed against the room type’s reference design, and must be manageable centrally, before it is used beyond a pilot room.', why: 'A product that works in one room and cannot be managed in fifty is a future exception fifty times over.', tests: ['interop_mixed_vendor', 'compute_certified_config'] },
    ],
    open: ['The wording by which a supplier acknowledges the standard.'],
    see: [CX, DRAW, KNOW],
  },
  {
    id: 'operations', title: 'Operations and lifecycle', aim: 'Faults found from a desk, fixed in order, and rooms retired on purpose.',
    principles: [
      { id: 'O-01', stage: 'operate', say: 'Monitor what leads to an action: whether a device is online, which firmware it runs and whether that has drifted, and the health of its port. Do not collect what nobody will act on.', why: 'A dashboard of everything is read by nobody.', tests: ['integ_monitoring_enrol', 'network_management_reach'] },
      { id: 'O-02', stage: 'operate', say: 'Support has tiers, and a fault passed to the supplier goes with its logs and evidence.', why: 'A supplier sent a description starts from the beginning; one sent evidence starts from the fault.', tests: ['integ_itsm', 'handover_support_path'] },
      { id: 'O-03', stage: 'operate', say: 'For a picture fault, collect the evidence before restarting anything, then work in order. Is it always, or sometimes? Protected content, or any content? Check power, input and source. Connect a known-good source straight to the display to divide the chain. Force a resolution known to work. Apply the standard capability profile. Check content protection from end to end. Only then cabling, power-saving settings and switching.', why: 'A restart often clears the fault and always clears the evidence.' },
      { id: 'O-04', stage: 'operate', say: 'For a network fault, work outward: link, power and port profile; segment and address; multicast membership; loss and errors; firmware drift; then a port known to be good.', why: 'Each step rules out a layer, so the order is the diagnosis.', tests: ['network_reachability', 'network_port_profile'] },
      { id: 'O-05', stage: 'operate', say: 'A room’s computer is kept to a baseline: a managed identity; a name and an asset tag that follow the pattern; updates released in stages, to the most important rooms last, with a way back; few and documented USB connections; one default camera, loudspeaker and microphone; a wired network; the right time.', why: 'Most conferencing faults are the room’s computer having quietly become different from its neighbours.', tests: ['uc_peripherals', 'compute_patch_baseline', 'compute_display_capability'], families: ['uc'] },
      { id: 'O-06', stage: 'operate', say: 'Equipment has a planned life: warranty tracked, a refresh window for each class of device, and a retirement that wipes it, archives its configuration and updates the inventory.', why: 'A device that is never retired is eventually removed by failure, at a time of its own choosing.', tests: ['handover_warranty'] },
      { id: 'O-07', stage: 'operate', say: 'Every figure on an estate dashboard is defined in words on the page that shows it. A figure nobody can define is not shown.', why: 'People act on dashboards. A count that means something different from what its label suggests sends them to the wrong room.' },
    ],
    open: ['The refresh window for each class of device.', 'The stages in which updates are released.'],
    see: [FI, ASSURE, PRO, SIGNAL],
  },
  {
    id: 'exceptions', title: 'Exceptions and revisions', aim: 'A standard that can bend in the open and change on the record.',
    principles: [
      { id: 'E-01', stage: 'govern', say: 'A departure from the standard is requested in writing before it is built: what is departed from, the technical reason, the risk, what reduces the risk, for how long, and how the room returns to standard.', why: 'An exception asked for afterwards is a report of something that has already happened.' },
      { id: 'E-02', stage: 'govern', say: 'Convenience, a deadline or a supplier’s preference is not, alone, a reason.', why: 'Each is always present. If any of them were enough there would be no standard.' },
      { id: 'E-03', stage: 'govern', say: 'A temporary exception has an end date; one that has outlived it is a failure of governance until it is closed or renewed. A permanent exception has a date on which it is looked at again.', why: 'Temporary arrangements are the most permanent things in a building.' },
      { id: 'E-04', stage: 'govern', say: 'Nobody approves their own exception.', why: 'The person asking has already decided.', noWaiver: 'A separation of duties; not open to exception.' },
      { id: 'E-05', stage: 'govern', say: 'Some rules are never excepted: critical security, mandatory safety, a legal duty, and the integrity of evidence. This manual marks each one.', why: 'These protect people outside the project, who were not asked.', noWaiver: 'This is the rule that makes the others hold.' },
      { id: 'E-06', stage: 'govern', say: 'The same exception asked for repeatedly is a sign that the standard should change.', why: 'The estate is telling the standard something.' },
      { id: 'E-07', stage: 'govern', say: 'The standard is versioned. Each revision says what changed, why, from when and what it applies to, so that a room is judged against the revision in force when it was built.', why: 'Otherwise every revision makes every existing room non-compliant overnight.' },
      { id: 'E-08', stage: 'govern', say: 'A change that the people affected were not told about counts as a failure. A revision is published with a note, and the standard is reviewed on a schedule and after a major incident.', why: 'A standard nobody knows has changed is two standards.', values: ['cadence'] },
    ],
    open: ['Who approves an exception, and who may not.', 'How a revision is announced.'],
    see: [EXC, BUILD, KNOW],
  },
];

export const ALL_PRINCIPLES: readonly Principle[] = CHAPTERS.flatMap((c) => c.principles);
export const principleById = (id: string) => ALL_PRINCIPLES.find((p) => p.id === id);
export const chapterOf = (principle: string) => CHAPTERS.find((c) => c.principles.some((p) => p.id === principle));
export const chapterById = (id: string) => CHAPTERS.find((c) => c.id === id);
export const STAGE_LABEL: Record<Stage, string> = { govern: 'Governance', design: 'Design', commission: 'Commissioning', operate: 'Operation' };

/** Plain-text search over the manual: every word of the question must appear in the rule, its reason or its chapter's title. */
export function searchManual(q: string): Array<{ chapter: Chapter; principle: Principle }> {
  const words = q.toLowerCase().split(/[^a-z0-9-]+/).filter((w) => w.length >= 2).slice(0, 8); if (!words.length) return [];
  const out: Array<{ chapter: Chapter; principle: Principle }> = [];
  for (const c of CHAPTERS) for (const p of c.principles) { const hay = `${p.id} ${c.title} ${p.say} ${p.why} ${p.check || ''} ${(p.values || []).map((v) => valueById(v)?.name || '').join(' ')}`.toLowerCase(); if (words.every((w) => hay.includes(w))) out.push({ chapter: c, principle: p }); }
  return out;
}
